    服务注册与发现客户端
    - 封装注册/注销/心跳逻辑
    - 提供服务发现 + 随机负载均衡
    """

    def __init__(self, registry_url: Optional[str] = None):
        self._registry_url = registry_url or RegistryConfig.URL

    # ---------- 注册 ----------

    def register(self, service_name: str, host: str, port: int) -> dict:
        """向注册中心注册服务"""
        try:
            resp = requests.post(
                f"{self._registry_url}/register",
                json={"name": service_name, "host": host, "port": port},
                timeout=5,
            )
            return resp.json()
        except Exception as e:
            print(f"⚠️  [Client] 注册失败: {e}")
            return {"error": str(e)}

    def deregister(self, service_name: str, host: str, port: int) -> dict:
        """从注册中心注销服务"""
        try:
            resp = requests.post(
                f"{self._registry_url}/deregister",
                json={"name": service_name, "host": host, "port": port},
                timeout=5,
            )
            return resp.json()
        except Exception as e:
            print(f"⚠️  [Client] 注销失败: {e}")
            return {"error": str(e)}

    def heartbeat(self, service_name: str, host: str, port: int) -> dict:
        """发送心跳"""
        try:
            resp = requests.post(
                f"{self._registry_url}/heartbeat",
                json={"name": service_name, "host": host, "port": port},
                timeout=3,
            )
            return resp.json()
        except Exception as e:
            return {"error": str(e)}

    # ---------- 发现 ----------

    def discover(self, service_name: str) -> Optional[str]:
        """
        发现服务实例，返回随机选择的 base_url
        例: "http://localhost:5001"
        """
        try:
            resp = requests.get(
                f"{self._registry_url}/service/{service_name}",
                timeout=3,
            )
            instances = resp.json()
            if not instances:
                return None
            instance = random.choice(instances)
            return f"http://{instance['host']}:{instance['port']}"
        except Exception as e:
            print(f"⚠️  [Client] 服务发现失败 ({service_name}): {e}")
            return None

    def discover_all(self, service_name: str) -> List[Dict[str, Any]]:
        """获取服务所有实例列表"""
        try:
            resp = requests.get(
                f"{self._registry_url}/service/{service_name}",
                timeout=3,
            )
            return resp.json() or []
        except Exception:
            return []

    # ---------- 代理 ----------

    def proxy_get(self, service_name: str, path: str, timeout: int = 5):
        """GET 代理请求"""
        return self._proxy(service_name, path, "GET", timeout=timeout)

    def proxy_post(self, service_name: str, path: str,
                   data: dict = None, timeout: int = 5):
        """POST 代理请求"""
        return self._proxy(service_name, path, "POST",
                           data=data, timeout=timeout)

