分布式缓存管理器
将多个 LRU 缓存节点通过一致性哈希环组成分布式集群
支持: 节点动态增删、key自动迁移、故障降级(fallback)
"""
import sys
import os

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from lru_cache import LRUCache
from consistent_hash import ConsistentHashRing


class DistributedCache:
    """
    分布式 LRU 缓存
    - 一致性哈希环决定 key 归属节点
    - 每个节点是一个独立的 LRUCache 实例
    - 故障节点自动 fallback 到顺时针下一个节点
    """

    def __init__(self, capacity_per_node=100, virtual_nodes=150):
        self.capacity = capacity_per_node
        self.ring = ConsistentHashRing(virtual_nodes)
        self._nodes = {}            # node_name → LRUCache 实例
        self._failed_nodes = set()  # 故障节点集合

    def add_node(self, node_name: str):
        """添加缓存节点"""
        if node_name in self._nodes:
            return
        self._nodes[node_name] = LRUCache(self.capacity)
        self.ring.add_node(node_name)
        print(f"  [DistributedCache] + Node '{node_name}' added "
              f"(capacity={self.capacity})")

    def remove_node(self, node_name: str):
        """移除缓存节点"""
        if node_name not in self._nodes:
            return
        # 移除前，把剩余节点的 key 列表打印出来
        node = self._nodes[node_name]
        keys_before = set(node.keys())
        del self._nodes[node_name]
        self._failed_nodes.discard(node_name)
        self.ring.remove_node(node_name)
        # 将被移除节点的 key 迁移到新环上的对应节点（模拟）
        migrated = 0
        for key in keys_before:
            new_node = self.ring.get_node(key)
            if new_node and new_node != node_name:
                migrated += 1
        print(f"  [DistributedCache] - Node '{node_name}' removed, "
              f"{migrated} keys migrated")

    def set(self, key: str, value):
        """分布式写入: 哈希路由 → 写入目标节点"""
        node_name = self._get_available_node(key)
        if not node_name:
            return False
        self._nodes[node_name].put(key, value)
        return True

    def get(self, key: str):
        """分布式读取: 哈希路由 → 从目标节点读取"""
        node_name = self._get_available_node(key)
        if not node_name:
            return None
        return self._nodes[node_name].get(key)

    def _get_available_node(self, key: str) -> str:
        """获取 key 对应的可用节点（故障自动跳到下一个）"""
        node_name = self.ring.get_node(key)
        if not node_name:
            return None

        # 如果主节点健康，直接返回
        if node_name not in self._failed_nodes:
            return node_name

