"""
服务注册中心 (Service Registry)
负责管理所有微服务的注册、发现、健康检查
"""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..'))

from flask import Flask, request, jsonify
import threading
import time
from typing import Dict, List, Any

from config import RegistryConfig


class ServiceRegistry:
    """
    服务注册表核心逻辑（可脱离 Flask 独立使用，便于测试）
    """

    def __init__(self, heartbeat_timeout: int = RegistryConfig.HEALTH_CHECK_TIMEOUT):
        self._registry: Dict[str, List[Dict[str, Any]]] = {}
        self._lock = threading.Lock()
        self._heartbeat_timeout = heartbeat_timeout

    def register(self, name: str, host: str, port: int) -> dict:
        with self._lock:
            if name not in self._registry:
                self._registry[name] = []
            for inst in self._registry[name]:
                if inst["host"] == host and inst["port"] == port:
                    inst["last_heartbeat"] = time.time()
                    return {"message": "服务已更新", "status": "updated"}
            self._registry[name].append({
                "host": host, "port": port,
                "status": "healthy", "last_heartbeat": time.time(),
            })
        return {"message": "注册成功", "status": "registered"}

    def deregister(self, name: str, host: str, port: int) -> dict:
        with self._lock:
            if name in self._registry:
                before = len(self._registry[name])
                self._registry[name] = [
                    i for i in self._registry[name]
                    if not (i["host"] == host and i["port"] == port)
                ]
                if len(self._registry[name]) < before:
                    return {"message": "注销成功", "status": "deregistered"}
        return {"message": "未找到服务", "status": "not_found"}

    def heartbeat(self, name: str, host: str, port: int) -> dict:
        with self._lock:
            if name in self._registry:
                for inst in self._registry[name]:
                    if inst["host"] == host and inst["port"] == port:
                        inst["last_heartbeat"] = time.time()
                        inst["status"] = "healthy"
                        return {"message": "心跳更新", "status": "ok"}
        return {"message": "未找到服务", "status": "not_found"}

    def get_instances(self, name: str) -> List[Dict[str, Any]]:
        now = time.time()
        instances = self._registry.get(name, [])
        healthy = [
            i for i in instances
            if (now - i["last_heartbeat"]) < self._heartbeat_timeout
        ]
        with self._lock:
            self._registry[name] = healthy
        return [
            {"host": i["host"], "port": i["port"]}
            for i in healthy
        ]

    def all_services(self) -> Dict[str, Any]:
        return {
            name: [
                {"host": i["host"], "port": i["port"],
                 "status": i["status"],
                 "last_heartbeat": i["last_heartbeat"]}
                for i in instances
            ]
            for name, instances in self._registry.items()
        }

    def health_check(self) -> dict:
        now = time.time()
        stats = {}
        with self._lock:
            for name, instances in self._registry.items():
                healthy = 0
                unhealthy = 0
                for inst in instances:
                    if (now - inst["last_heartbeat"]) < self._heartbeat_timeout:
                        healthy += 1
                    else:
                        inst["status"] = "unhealthy"
                        unhealthy += 1
                stats[name] = {
                    "total": len(instances),
                    "healthy": healthy,
                    "unhealthy": unhealthy,
                }
        return stats


