class RateLimiter:
    """滑动窗口限流器"""

    def __init__(self, max_requests: int = GatewayConfig.RATE_LIMIT,
                 window: int = GatewayConfig.RATE_WINDOW):
        self._max = max_requests
        self._window = window
        self._store: Dict[str, List[float]] = {}

    def allow(self, ip: str) -> bool:
        now = time.time()
        if ip not in self._store:
            self._store[ip] = []
        self._store[ip] = [
            t for t in self._store[ip] if now - t < self._window
        ]
        if len(self._store[ip]) >= self._max:
            return False
        self._store[ip].append(now)
        return True


